16:     const t = Math.min(1, Math.max(0, (z + l / 2) / l)); // 0 at front, 1 at rear
17:     if (y > 0) {
18:       y -= frontDrop * Math.pow(1 - t, 1.35);
19:       x *= topFrontScale + (1 - topFrontScale) * t;
20:     } else {
21:       x *= bottomFrontScale + (1 - bottomFrontScale) * t;
22:     }
23:     pos.setXYZ(i, x, y, z);
24:   }
25:   geo.computeVertexNormals();
26:   return geo;
27: }
