49: function wheelGeometry(r, width) {
50:   const key = `${r.toFixed(3)}:${width.toFixed(3)}`;
51:   if (wheelGeometryCache.has(key)) return wheelGeometryCache.get(key);
52: 
53:   const tireParts = [new THREE.CylinderGeometry(r, r, width, 22).rotateZ(Math.PI / 2)];
54:   const rimParts = [];
55:   for (const side of [-1, 1]) {
56:     tireParts.push(
57:       new THREE.TorusGeometry(r * 0.9, r * 0.09, 5, 18)
58:         .rotateY(Math.PI / 2)
59:         .translate(side * width * 0.5, 0, 0)
60:     );
61:     rimParts.push(
62:       new THREE.TorusGeometry(r * 0.58, r * 0.045, 5, 18)
63:         .rotateY(Math.PI / 2)
64:         .translate(side * (width * 0.5 + 0.012), 0, 0),
65:       new THREE.CylinderGeometry(r * 0.15, r * 0.15, width * 0.36, 10)
66:         .rotateZ(Math.PI / 2)
67:         .translate(side * (width * 0.5 + 0.01), 0, 0)
68:     );
69:     for (let i = 0; i < 5; i++) {
70:       rimParts.push(
71:         new THREE.BoxGeometry(0.028, r * 0.78, r * 0.09)
72:           .rotateX((i / 5) * Math.PI * 2)
73:           .translate(side * (width * 0.5 + 0.006), 0, 0)
74:       );
75:     }
76:   }
77:   tireParts.push(new THREE.CylinderGeometry(r * 0.44, r * 0.44, width * 0.3, 14).rotateZ(Math.PI / 2));
78: 
79:   const geo = {
80:     tire: mergeGeometries(tireParts),
81:     rim: mergeGeometries(rimParts),
82:   };
83:   for (const g of tireParts) g.dispose?.();
84:   for (const g of rimParts) g.dispose?.();
85:   wheelGeometryCache.set(key, geo);
86:   return geo;
87: }
