97: function loftGeometry(sections, six = false) {
98:   const verts = [];
99:   const idx = [];
100:   const P = six ? 6 : 4;
101:   for (const sec of sections) {
102:     if (six) {
103:       const midY = sec.bottom + (sec.top - sec.bottom) * 0.52;
104:       verts.push(
105:         -sec.w / 2, sec.bottom, sec.z,
106:         -sec.w * 0.492, midY, sec.z,
107:         -sec.w * 0.425, sec.top, sec.z,
108:         sec.w * 0.425, sec.top, sec.z,
109:         sec.w * 0.492, midY, sec.z,
110:         sec.w / 2, sec.bottom, sec.z
111:       );
112:     } else {
113:       verts.push(
114:         -sec.w / 2, sec.bottom, sec.z,
115:         -sec.w * 0.44, sec.top, sec.z,
116:         sec.w * 0.44, sec.top, sec.z,
117:         sec.w / 2, sec.bottom, sec.z
118:       );
119:     }
120:   }
121:   const n = sections.length;
122:   for (let i = 0; i < n - 1; i++) {
123:     for (let a = 0; a < P; a++) {
124:       const b = (a + 1) % P;
125:       const a0 = i * P + a;
126:       const a1 = i * P + b;
127:       const b0 = (i + 1) * P + a;
128:       const b1 = (i + 1) * P + b;
129:       idx.push(a0, b0, b1, a0, b1, a1);
130:     }
131:   }
132:   const last = (n - 1) * P;
133:   for (let a = 1; a < P - 1; a++) {
134:     idx.push(0, a, a + 1);
135:     idx.push(last, last + a + 1, last + a);
136:   }
137:   const geo = new THREE.BufferGeometry();
138:   geo.setAttribute("position", new THREE.Float32BufferAttribute(verts, 3));
139:   geo.setIndex(idx);
140:   geo.computeVertexNormals();
141:   return geo;
142: }
