147:     this.targetEnemy = null;
148:     this.ended = false;
149:     this.endReason = "";
150:     this.shake = 0;
151:     this.bestCombo = 1;
152: 
153:     for (const list of [this.traffic, this.enemies, this.coresList, this.ramps]) {
154:       for (const e of list) {
155:         e.active = false;
156:         e.group.visible = false;
157:         e.passed = false;
158:         e.scored = false;
159:         e.collided = false;
160:       }
161:     }
162:     this.kitt.group.position.set(this.carX, 0, 0);
163:     this.kitt.group.rotation.set(0, 0, 0);
164:     this.kitt.group.visible = true;
165:     void instant;
166:   }
