212:   getStats() {
213:     const score = Math.floor(this.score);
214:     let rank = "D";
215:     let quote = "“Michael, perhaps we should review the manual.”";
216:     if (score >= 16000) {
217:       rank = "S";
218:       quote = "“Michael, that was almost elegant.”";
219:     } else if (score >= 10000) {
220:       rank = "A";
221:       quote = "“A commendable performance, Michael.”";
222:     } else if (score >= 6000) {
223:       rank = "B";
224:       quote = "“The Foundation will be pleased.”";
225:     } else if (score >= 3000) {
226:       rank = "C";
227:       quote = "“Not bad for a machine.”";
228:     }
229:     return {
230:       score,
231:       distance: this.distance / 1609.34,
232:       topSpeed: Math.round(this.topSpeed * 2.23694),
233:       kills: this.kills,
234:       cores: this.cores,
235:       bestCombo: this.bestCombo || 1,
236:       rank,
237:       quote,
238:       reason: this.endReason,
239:     };
240:   }
