254:   _spawnTrafficAt(z, laneIndex, speed) {
255:     const e = this.traffic.find((t) => !t.active);
256:     if (!e) return null;
257:     const lane = LANES[clamp(Math.round(laneIndex), 0, 3)];
258:     e.active = true;
259:     e.passed = false;
260:     e.scored = false;
261:     e.collided = false;
262:     e.z = z;
263:     e.x = lane + (Math.random() - 0.5) * 0.5;
264:     e.speed = speed;
265:     e.group.visible = true;
266:     e.group.position.set(e.x, 0, e.z);
267:     return e;
268:   }
