270:   _spawnTraffic() {
271:     if (this.traffic.filter((t) => t.active).length >= 11) return;
272:     const laneIndex = (Math.random() * 4) | 0;
273:     const lane = LANES[laneIndex];
274:     for (const t of this.traffic) {
275:       if (!t.active) continue;
276:       if (Math.abs(t.x - lane) < 2.6 && t.z < -60 && t.z > -420) return;
277:     }
278:     const kindRoll = Math.random();
279:     let chosen = null;
280:     for (const t of this.traffic) {
281:       if (t.active) continue;
282:       const fits = kindRoll < 0.18 ? t.kind === "truck" : kindRoll < 0.44 ? t.kind === "suv" : t.kind === "sedan";
283:       if (fits) {
284:         chosen = t;
285:         break;
286:       }
287:     }
288:     if (!chosen) chosen = this.traffic.find((t) => !t.active);
289:     if (!chosen) return;
290:     const speed = chosen.kind === "truck" ? 23 + Math.random() * 6 : chosen.kind === "suv" ? 27 + Math.random() * 7 : 31 + Math.random() * 8;
291:     chosen.active = true;
292:     chosen.passed = false;
293:     chosen.scored = false;
294:     chosen.collided = false;
295:     chosen.z = -360 - Math.random() * 60;
296:     chosen.x = lane + (Math.random() - 0.5) * 0.55;
297:     chosen.speed = speed;
298:     chosen.group.visible = true;
299:     chosen.group.position.set(chosen.x, 0, chosen.z);
300:   }
